import fitz
src=fitz.open('report-typst-original.pdf')
out=fitz.open('report-prepress.pdf')
def fonts(d):
 result={}
 for page in d:
  for f in page.get_fonts(): result[f[0]]=f
 return result
base=lambda name:name.split('+',1)[-1]
maps={base(f[3]):src.xref_stream(int(src.xref_get_key(f[0],'ToUnicode')[1].split()[0])) for f in fonts(src).values()}
for f in fonts(out).values():
 out.update_stream(int(out.xref_get_key(f[0],'ToUnicode')[1].split()[0]),maps[base(f[3])])
out.save('report-equivalent.pdf',garbage=4,deflate=True)
out.close()
d=fitz.open('report-equivalent.pdf')
d.save('report-equivalent-compact.pdf',garbage=4,deflate=True,use_objstms=1)
